'use strict';
const HOME_ETFS=['SPY','QQQ','DIA','IWM','TLT','GLD'];
const HOME_STOCKS=['NVDA','AAPL','MSFT','AMZN','GOOG','TSLA','BE','INTC'];
const HOME_NAMES={SPY:'S&P 500',QQQ:'Nasdaq 100',DIA:'Dow Jones',IWM:'Russell 2000',TLT:'Long-term Treasuries',GLD:'Gold',NVDA:'NVIDIA',AAPL:'Apple',MSFT:'Microsoft',AMZN:'Amazon',GOOG:'Alphabet',TSLA:'Tesla',BE:'Bloom Energy',INTC:'Intel'};
let homeBusy=false;
function latestPurchases(rows=data){return rows.filter(r=>r.type==='Purchase').sort((a,b)=>b.traded.localeCompare(a.traded)||(disclosedDate(b)||'').localeCompare(disclosedDate(a)||'')).slice(0,6)}
function miniChart(p,symbol){const points=chartPoints(p,'1M');if(points.length<2)return '<span class="mini-empty">History unavailable</span>';const values=points.map(p=>p[1]),lo=Math.min(...values),hi=Math.max(...values),path=values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1)*160).toFixed(1)},${(37-(v-lo)/Math.max(.01,hi-lo)*32).toFixed(1)}`).join(' ');return `<svg viewBox="0 0 160 42" role="img" aria-label="${esc(symbol)} one month closing prices"><path d="${path}" fill="none" stroke="${values.at(-1)>=values[0]?'#16805a':'#bd4141'}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function quoteCard(symbol){const p=PRICES[symbol],delta=p?.previousClose?(p.latest/p.previousClose-1)*100:null,saved=workspaceState.symbols.includes(symbol);return `<article class="quote-card"><div class="quote-card-top"><button class="quote-link" data-ticker="${symbol}"><b>${symbol}</b><small>${esc(HOME_NAMES[symbol]||p?.name||symbol)}</small></button><button class="bookmark-stock ${saved?'saved':''}" data-bookmark="${symbol}" aria-label="${saved?'Remove':'Bookmark'} ${symbol}" aria-pressed="${saved}" ${!workspaceReady||workspaceBusy?'disabled':''}>${saved?'★':'☆'}</button></div><button class="quote-chart" data-ticker="${symbol}" aria-label="Open ${symbol} chart"><div><strong>${p?money(p.latest,p.currency):'—'}</strong><span class="${delta===null?'muted':delta>=0?'gain':'loss'}">${delta===null?'—':signed(delta)} <small>day</small></span></div>${miniChart(p,symbol)}</button><small class="quote-date">${p?'Close '+date(p.asOf)+(p.stale?' · stale':''):'Loading quote…'} · 1M chart</small></article>`}
function renderAccount(){const user=workspaceState.user;$('#accountControls').innerHTML=user?`<span class="account-email" title="${esc(user.email)}">${esc(user.email)}</span><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a>`:'<a class="account-signin" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a>';$('#bookmarkStatus').textContent=user?'Saved to your ChatGPT account':'Guest bookmarks · this browser. Sign in to sync across devices.';}
function renderHome(){
 if(!$('#homeView'))return;
 $('#homePurchases').innerHTML=latestPurchases().map(r=>`<tr><td><button class="home-person" data-person="${esc(r.person)}">${esc(r.person)}</button><small>${esc(r.owner)}</small></td><td><button class="home-ticker" data-ticker="${esc(r.ticker)}">${esc(r.ticker)}</button><small>${esc(r.asset)}</small></td><td>${date(r.traded)}</td><td>${disclosedDate(r)?date(disclosedDate(r)):'Unknown'}</td><td>${esc(r.amount)}</td><td class="${(priceReturn(r)?.pct||0)>=0?'gain':'loss'}">${priceReturn(r)?percent(priceReturn(r)):'—'}${r.asset==='Call options'?'<small>stock only</small>':''}</td><td><button class="row-details" data-detail="${esc(r.id)}" aria-label="Details for ${esc(r.person)} ${esc(r.ticker)} purchase">↗</button></td></tr>`).join('')||'<tr><td colspan="7">No purchases in the loaded disclosures.</td></tr>';
 $('#homeETFs').innerHTML=HOME_ETFS.map(quoteCard).join('');$('#homeStocks').innerHTML=HOME_STOCKS.map(quoteCard).join('');
 $('#homeBookmarks').innerHTML=workspaceState.symbols.map(s=>`<span class="favorite-chip"><button data-ticker="${esc(s)}">${esc(s)} <b>${PRICES[s]?money(PRICES[s].latest,PRICES[s].currency):'—'}</b></button><button data-bookmark="${esc(s)}" aria-label="Remove ${esc(s)} bookmark" ${workspaceBusy?'disabled':''}>×</button></span>`).join('')||'<span class="muted">Tap a star to bookmark a stock.</span>';renderAccount();
}
async function refreshHome(){if(homeBusy)return;homeBusy=true;renderHome();try{for(const symbols of [HOME_ETFS,HOME_STOCKS]){await loadMarketPrices(symbols);renderHome()}}finally{homeBusy=false}}
if(typeof window!=='undefined'){
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-bookmark]');if(!b||workspaceBusy||!workspaceReady)return;const symbol=b.dataset.bookmark;await workspaceAction({kind:'watch',symbol,enabled:!workspaceState.symbols.includes(symbol)});renderHome()});
 $('#homeTickerSearch').onsubmit=e=>{e.preventDefault();openStock($('#homeTickerInput').value)};
 renderHome();refreshHome();setInterval(()=>{if(!document.hidden)refreshHome()},15*60000);
}
